SELECT id, store_name, city, region, opened_date, sqft, AVG(sqft) OVER (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS sqft_avg_2_prior, NTILE(5) OVER (PARTITION BY region, city ORDER BY sqft DESC, id) AS sqft_bucket, SUM(sqft) OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft FROM stores
